                  const line = dataLine(rows[i], spec)
                  if (!GUID.test(line[0])) throw new Error(`a record of ${spec.def.label} came without its id`)   // (it couldn't be matched or saved)
                  // (a site setting whose name suggests a secret, or that has no name: its value as its fingerprint, saved
                  // and compared so)
                  if (spec.secretAt && isStr(line[spec.secretAt]) && (!isStr(rows[i][spec.def.primaryName]) || SECRET.test(rows[i][spec.def.primaryName]))) line[spec.secretAt] = { '#sha256': await sha256(line[spec.secretAt]), length: line[spec.secretAt].length }
