    const pump = (async () => {
      const r = cs.readable.getReader()
      for (;;) { const { done, value } = await r.read(); if (done) return; chunks.push(value); size += value.byteLength; if (size >= 8 * 1048576) { blobs.push(new Blob(chunks)); chunks = []; size = 0 } }
    })()
