        async done() { if (p.state !== 'open') return; await flush(p); p.blob = p.gz ? await p.gz.close() : null; p.gz = null; p.state = 'complete' },
        fail(why) { if (p.state === 'failed') return; if (p.state === 'open') { total -= p.lines; size -= p.bytes } if (p.gz) p.gz.abort(); Object.assign(p, { state: 'failed', why: String(why || ''), gz: null, buf: [], len: 0, blob: null, lines: 0, bytes: 0 }) },
