      if (!A.language && def.language) A.language = def.language   // (the language of your labels)
      if (!h || h.read !== 'complete') { A.tables.set(s.t, unreadTable(def, '', 'notRead')); table(s.t, 'not', { state: h ? 'failedB' : 'noSnapshot' }); continue }
