    savedquery: dict({ querytype: dict({ 0: 'Public', 1: 'Advanced Find', 2: 'Associated', 4: 'Quick Find', 64: 'Lookup' }), statecode: dict({ 0: 'Active', 1: 'Inactive' }), statuscode: dict({ 1: 'Active', 2: 'Inactive' }) }),
