  const cv = { page: 'overview', sol: '', st: 'diffs', um: '', type: '', q: '', fold: new Map(), more: new Map(), msOpen: false, sameOpen: false, order: 'ab', from: '', gen: 0, ovCur: '', gtk: false, same: false, ecur: '', item: null }
