  const verCmp = (x, y) => { const p = String(x || '').split('.'), q = String(y || '').split('.'); for (let i = 0; i < Math.max(p.length, q.length); i++) { const d = (Number(p[i]) || 0) - (Number(q[i]) || 0); if (d) return d } return 0 }
  const day = (d) => { const t = d ? new Date(`${d}T12:00:00Z`) : null; return !t || isNaN(t) ? '' : t.toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' }) }
