      const ks = f.changedKeys.map((k) => cmpPropLabel(k, f.kind)), w = ks.length ? `${cap(andList(ks))} ${ks.length === 1 && !severalOf(ks[0]) ? 'differs' : 'differ'}` : 'Its definition differs'   // ("Privileges differ", "Runs as differs")
      return plus(cat(w), f.layer && !f.ua && !f.ub ? cat(f.layer) : null)
