    const top = dcmp.notes.warn.filter((x) => D1_TOP.has(x.k))
    lvBox('dv', 1).innerHTML = `<div class="cv-body rs-body" id="dvBody">${top.length ? `<div class="rs-notes">${top.map(rsNote).join('')}</div>` : ''}<section class="rs-sheet rs-ov" id="dvSheet">`
      + `<div class="rs-find${d1FindShown() ? ' rs-open' : ''}" id="dvFind" role="search" aria-label="Find a table"><div class="rs-findg"><label class="input">${icon('search')}<input type="search" id="dvTq" placeholder="Find a table" aria-label="Find a table" autocomplete="off" value="${esc(dv.oq)}"></label></div></div>`
      + `<div class="rs-grid" role="grid" id="dvOv" aria-label="The tables compared">${d1Lanes()}<div class="rs-vl" id="dvOvRows"></div></div></section>${d1Gtk()}</div>`
    d1vl = vlist($('dvOvRows'), $('dvBody'), { height: d1Height, mode: d1Mode, sticky: () => { const l = root.querySelector('#dvOv .rs-lanes'); return l ? l.offsetHeight : 0 }, page: () => { const b = $('dvBody'), l = root.querySelector('#dvOv .rs-lanes'); return b ? Math.max(1, Math.floor((b.clientHeight - (l ? l.offsetHeight : 0)) / (d1Narrow() ? 75 : 69)) - 1) : 8 }, onCur: (k) => { dv.ovCur = k } })
    lvList.dv[1] = d1vl
