      const dk = cols.filter((k) => kinds.has(k) && !odd(k)), uk = cols.filter((k) => kinds.has(k) && odd(k)), sk = cols.filter((k) => !kinds.has(k) && !(skipName && plan.cols[k].ia === plan.nameA))
