      if (uk.length) body += sbsGroup('unk', plural(uk.length, "column couldn't be compared", "columns couldn't be compared")) + uk.map(diffRow).join('')
      const sameG = () => { d3Rest = sk.length > D3_FIRST ? { k: sk.slice(D3_FIRST), make: sameRow, gen: ++d3Gen } : null; return sbsGroup('same', 'The same in both', plural(sk.length, 'column'), true) + sk.slice(0, D3_FIRST).map(sameRow).join('') + (d3Rest ? `<div class="rs-rest" id="dvRecRest" data-gen="${d3Rest.gen}"></div>` : '') }
