  // The JSON tab: each environment's record as compared and as stored (recordLayers), Copy and Download as today.
  function d3JsonText(L) { const raw = (L[dv.rec.jl] || {})[(CMP_JSON[dv.rec.json] || CMP_JSON.all)[0]] || '', j = parseJson(raw); return { raw, j, text: j && typeof j === 'object' ? indentJson(raw) || raw : raw } }
