    const L = recordLayers(tr, plan, r, la, lb), x = dv.rec
    if (x.jl >= L.length) x.jl = 0
    const t = d3JsonText(L), what = (CMP_JSON[x.json] || CMP_JSON.all)[1]
    return `<div class="rs-jtools"><label class="fld">Environment <select class="sel" id="dvRecEnv">${L.map((l, i) => `<option value="${i}"${i === x.jl ? ' selected' : ''}>${esc(dEnv(l.msdyn_solutionname === SIDE.A ? 'a' : 'b', true))}</option>`).join('')}</select></label>`
